// Pure host module/cache/stream glue. All rotary math is generated by NineToothed.
#include <hip/hip_runtime_api.h>
#include <array>
#include <atomic>
#include <cstdint>
#include <mutex>
#include <string>
#include <unordered_map>
namespace {
struct Module { hipModule_t module; hipFunction_t function; };
std::mutex mutex;
std::unordered_map<std::string,Module> modules;
std::array<std::atomic<uint64_t>,5> stats{};
std::array<std::array<std::atomic<uint64_t>,23>,64> per_device{};
thread_local std::string error;
void check(hipError_t status) { if (status!=hipSuccess) throw std::string(hipGetErrorString(status)); }
int pair_index(const std::string &path) {
    const std::array<std::string,6> inputs{"i32","i64","f16","bf16","f32","f64"};
    const std::array<std::string,3> outputs{"f16","bf16","f32"};
    for(int i=0;i<6;++i) for(int j=0;j<3;++j) if(path.find("/"+inputs[i]+"_to_"+outputs[j]+"/")!=std::string::npos) return 3*i+j;
    throw std::string("Unknown rotary pair");
}
}
extern "C" const char *minimax_nine_rotary_error() { return error.c_str(); }
extern "C" void minimax_nine_rotary_statistics(uint64_t *values) { for(size_t i=0;i<5;++i) values[i]=stats[i].load(); }
extern "C" void minimax_nine_rotary_device_statistics(int device,uint64_t *values) {
    for(size_t i=0;i<23;++i) values[i]=(device>=0 && device<64) ? per_device[device][i].load() : 0;
}
extern "C" int minimax_nine_rotary_launch(const char *binary,unsigned grid,void *stream,void **arguments) {
    error.clear();
    try {
        if (!binary || !grid || !stream || !arguments) throw std::string("Invalid rotary host arguments");
        int device=-1; check(hipGetDevice(&device));
        if(device<0 || device>=64) throw std::string("Rotary diagnostic capacity exceeded");
        const int pair=pair_index(binary);
        auto &local=per_device[device];
        hipFunction_t function=nullptr;
        {
            std::lock_guard<std::mutex> lock(mutex);
            const auto key=std::to_string(device)+":"+binary;
            auto found=modules.find(key);
            if(found==modules.end()) {
                hipDeviceProp_t prop{}; check(hipGetDeviceProperties(&prop,device));
                const std::string arch=prop.gcnArchName;
                if(arch.substr(0,arch.find(':'))!="gfx936" || prop.warpSize!=64) throw std::string("Expected gfx936/warp64");
                hipModule_t module=nullptr; check(hipModuleLoad(&module,binary));
                const auto result=hipModuleGetFunction(&function,module,"minimax_nine_h3_rotary");
                if(result!=hipSuccess) { (void)hipModuleUnload(module); check(result); }
                modules.emplace(key,Module{module,function}); ++stats[1]; ++local[1];
            } else function=found->second.function;
        }
        check(hipModuleLaunchKernel(function,grid,1,1,256,1,1,0,static_cast<hipStream_t>(stream),arguments,nullptr));
        ++stats[0]; stats[2]=reinterpret_cast<uintptr_t>(stream); stats[3]=device; stats[4]=grid;
        ++local[0]; local[2]=reinterpret_cast<uintptr_t>(stream); local[3]=device; local[4]=grid; ++local[5+pair];
        return 0;
    } catch(const std::string &value) { error=value; }
      catch(const std::exception &value) { error=value.what(); }
      catch(...) { error="Unknown host exception"; }
    return 1;
}
